import{_ as s,o as a,c as i,a3 as r,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/grundschule/tutorials-gs-versetzungstabelle-statistikjahrgangtabelle.png",l="/bilder/grundschule/tutorials-gs-versetzungstabelle-statistikjahrgangtabelle-fs.png",g="/bilder/grundschule/tutorials-gs-versetzungstabelle-versetzungstabelle.png",h="/bilder/grundschule/tutorials-gs-versetzungstabelle-klassendetails-standardklasse.png",u="/bilder/grundschule/tutorials-gs-versetzungstabelle-klassendetails-j-uin-spe.png",o="/bilder/grundschule/tutorials-gs-versetzungstabelle-versetzungstabelle-fs.png",v=JSON.parse('{"title":"Frühere Versetzungstabellen für jahrgangsgemischte Klassen","description":"","frontmatter":{"title":"Frühere Versetzungstabellen für jahrgangsgemischte Klassen","source_pageid":1212,"source_revision":4230},"headers":[],"relativePath":"zeugnisse/grundschule/versetzungstabelle-bei-jahrgangsgemischten-klassen-tutorial.md","filePath":"zeugnisse/grundschule/versetzungstabelle-bei-jahrgangsgemischten-klassen-tutorial.md"}'),c={name:"zeugnisse/grundschule/versetzungstabelle-bei-jahrgangsgemischten-klassen-tutorial.md"};function b(m,n,p,f,k,z){return a(),i("div",null,[...n[0]||(n[0]=[r('<h1 id="fruhere-versetzungstabellen-fur-jahrgangsgemischte-klassen" tabindex="-1">Frühere Versetzungstabellen für jahrgangsgemischte Klassen <a class="header-anchor" href="#fruhere-versetzungstabellen-fur-jahrgangsgemischte-klassen" aria-label="Permalink to &quot;Frühere Versetzungstabellen für jahrgangsgemischte Klassen&quot;">​</a></h1><p>Die Beispiele erläutern jahrgangsgemischte Klassen mit den früheren Jahrgängen E1 bis E3. Für die getrennte Erfassung von Jahrgang und EP-Jahr in SchILD-NRW 3 beachten Sie die verlinkten neueren Anleitungen.</p><p>Für SchILD-NRW 3 verwenden Sie <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">Die Jahre der Schuleingangsphase eintragen</a> und <a href="/schild3/unterricht-kataloge/jahrgaenge-schulbezogene-kataloge.html">Jahrgänge und ihre Statistikzuordnung festlegen</a>. Die folgenden Tabellen bleiben als frühere Verfahrensbeispiele erhalten.</p><h2 id="die-fruhere-jahrgangstabelle" tabindex="-1">Die frühere Jahrgangstabelle <a class="header-anchor" href="#die-fruhere-jahrgangstabelle" aria-label="Permalink to &quot;Die frühere Jahrgangstabelle&quot;">​</a></h2><p><a href="/bilder/grundschule/tutorials-gs-versetzungstabelle-statistikjahrgangtabelle.png"><img src="'+d+'" alt="Grundschule: Die Tabelle Kataloge ➜ Statistikjahrgänge, in denen die in der Schule vorhandenen Jahrgänge definiert werden. Die Sek.-Stufe ist die Pr (Primarstufe)." loading="lazy"></a></p><p><em><strong>Grundschule:</strong> Die Tabelle Kataloge ➜ Statistikjahrgänge, in denen die in der Schule vorhandenen Jahrgänge definiert werden. Die Sek.-Stufe ist die Pr (Primarstufe).</em></p><p>In allen <em>Grundschulen</em> muss die Tabelle <em>Kataloge</em> ➜ <strong>Statistikjahrgänge</strong> unabhängig von der Unterrichtsorganisation wie im Screenshot abgebildet werden.</p><p>Die Tabelle enthält die Schülerjahrgänge E1, E2, E3, 03 und 04 mit den zugehörigen <em>Restabschnitten</em>, also in der Regel die zu Beginn des Jahrgangs verbleibenden Halbjahre, und bildet somit ab, welche Jahrgänge grundsätzlich in der Schule vorkommen.</p><p>Die Bezeichnungen für die Schuleingangsphase E1 und E2 werden statt der Jahrgangsbezeichnungen 01 und 02 für die ersten beiden Jahrgänge der Schuleingangsphase verwendet.</p><p>Die Jahrgangsbezeichnung E3 ist Schülern vorbehalten, welche die zweite Klasse wiederholen und somit ein drittes Jahr in der Schuleingangsphase bleiben. Ebenso werden Schüler, die das erste Jahr der Schuleingangsphase wiederholen und damit ihre &quot;zweite 1. Klasse&quot; im Jahrgang E2 sind, in ihrer dann folgenden 2. Klasse im Jahrgang E3 erscheinen.</p><p>Die oben abgebildete Tabelle zeigt eine sinnvolle Sortierung der Jahrgänge. Um eine eigene Sortierung vornehmen zu können, wird die <strong>Sortierung</strong> oben in der Kopfzeile auf <em>Benutzerdefiniert</em> gestellt. Dann können die Einträge mittels der schwarzen Pfeile links verschoben werden.</p><p><a href="/bilder/grundschule/tutorials-gs-versetzungstabelle-statistikjahrgangtabelle-fs.png"><img src="'+l+'" alt="Förderschule: Der obere Teil der Tabelle entspricht der Grundschule, dann schließen sich ab Jahrgang 05 die weiterführenden Jahrgänge an. Die Restabschnitte setzen mit dem Jahrgang 05 bei den verbleibenden 12 Halbjahren neu an. Die Sek.-Stufe ändert sich von Pr auf SI." loading="lazy"></a></p><p><em><strong>Förderschule:</strong> Der obere Teil der Tabelle entspricht der Grundschule, dann schließen sich ab Jahrgang 05 die weiterführenden Jahrgänge an. Die <strong>Restabschnitte</strong> setzen mit dem Jahrgang 05 bei den verbleibenden 12 Halbjahren neu an. Die <strong>Sek.-Stufe</strong> ändert sich von Pr auf SI.</em></p><p>In der <em>Förderschule</em> schließen sich an diesen Primarstufenblock die höheren Jahrgangstufen mit den neuen <strong>Restabschnitt</strong>en von Jahrgang 05 bis 10 und der neuen <strong>Sek.-Stufe</strong>, der <em>SI</em>, an.</p><h2 id="klassenversetzungstabelle" tabindex="-1">Klassenversetzungstabelle <a class="header-anchor" href="#klassenversetzungstabelle" aria-label="Permalink to &quot;Klassenversetzungstabelle&quot;">​</a></h2><p><a href="/bilder/grundschule/tutorials-gs-versetzungstabelle-versetzungstabelle.png"><img src="'+g+'" alt="Die Versetzungstabelle wird über Kataloge ➜ Klassen-/Versetzungstabelle bearbeitet. Hier sind alle Klassen der Schule mit all ihren Details definiert und ein Teil davon ist, in welche Klasse bei der Versetzung folgt." loading="lazy"></a></p><p><em>Die Versetzungstabelle wird über Kataloge ➜ Klassen-/Versetzungstabelle bearbeitet. Hier sind alle Klassen der Schule mit all ihren Details definiert und ein Teil davon ist, in welche Klasse bei der Versetzung folgt.</em></p><p>In der <em>Klassen-/Versetzungstabelle</em> werden die Klassen definiert.</p>',18),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),t("Tipp")]),e("p",null,[t("Schauen Sie hierzu grundsätzlich in den Artikel zu dieser in der Rubrik "),e("em",null,"Kataloge"),t(" dieses Wikis.")])],-1),r('<p>In diesem Tutorial ist die Hauptansicht relevant, in der tabellarisch die <strong>Klassen</strong> und ihre <strong>Folgeklassen</strong> aufgeführt werden.</p><p>Bei den <strong>Klassen</strong> kann die <strong>Interne Bezeichnung</strong> frei gewählt werden. Ob Ihre Schule die ersten Klassen 1.1 und 1.2 oder 1A und 1B oder die &quot;Adler&quot; und die &quot;Bieber&quot; nennt, ist Ihnen überlassen. Beachten Sie die Zeichenbeschränkung, die nur kurze Tierbezeichnungen zulässt.</p><p>Die <strong>Parallelität</strong> hingegen ist statistikrelevant und folgt dem Schema, dass zuerst zweistellig der Jahrgang steht, dann folgt aufsteigend das Alphabet in Großbuchstaben, wie es auch im Beleg mit den Klassendaten (KLD) im Statistikprogramm ASDPC32 gehandhabt wird: also für die ersten beiden Klassen des 1. Jahrgangs sind dies 1EA, 1EA oder im dritten Jahrgang werden die ersten beiden Klassen als 03A und 03B erfasst.</p><p>In dieser Tabelle ist die Schule noch auf zwei Teilstandorte (Spalte <strong>TSO</strong>) mit den Standorten <em>A</em> und <em>B</em> aufgeteilt.</p><h2 id="beispiele-fur-klassenversetzungstabellen" tabindex="-1">Beispiele für Klassenversetzungstabellen <a class="header-anchor" href="#beispiele-fur-klassenversetzungstabellen" aria-label="Permalink to &quot;Beispiele für Klassenversetzungstabellen&quot;">​</a></h2><h3 id="grundschule-mit-jahrgangsbezogenem-unterricht" tabindex="-1">Grundschule mit jahrgangsbezogenem Unterricht <a class="header-anchor" href="#grundschule-mit-jahrgangsbezogenem-unterricht" aria-label="Permalink to &quot;Grundschule mit jahrgangsbezogenem Unterricht&quot;">​</a></h3><p><a href="/bilder/grundschule/tutorials-gs-versetzungstabelle-klassendetails-standardklasse.png"><img src="'+h+'" alt="Die Details einer Klasse mit &quot;normalem&quot; jahrgangsbezogenem Unterricht." loading="lazy"></a></p><p><em>Die Details einer Klasse mit &quot;normalem&quot; jahrgangsbezogenem Unterricht.</em></p><p>Die <em>Klassen-Versetzungstabelle</em> an sich wird bei jahrgangsbezogenem Unterricht wie im Beispielscreenshot oben ausgefüllt.</p><p>Im Screenshot rechts sind die Details einer <em>Beispielklasse</em> zu sehen.</p><p>Es gibt keine Besonderheiten zu beachten:</p><ul><li>es werden lediglich die Klassenjahrgänge <em>1E</em>, <em>2E</em>, <em>03</em> und <em>04</em> verwendet.</li><li>die <strong>Parallelität</strong> wird bei den Klassen nur alphabetisch A, B, C, ... hochgesetzt.</li><li>bei jeder <strong>Klassenart</strong> handelt es sich um eine <em>Regelklasse</em>.</li><li>es wird eine <strong>Folgeklasse</strong> gesetzt. Im Jahrgang 1E gibt es keine Vorgängerklasse, im Jahrgang 04 bleibt die Folgeklasse leer.</li></ul><p>Ist das Feld <strong>Folgeklasse</strong> leer, versetzt Schild diese Schüler in den <strong>Status</strong> <em>Abschluss</em>, sofern kein anderer Versetzungsvermerk gesetzt wurde und damit sind diese Schüler keine aktiven Schüler der Schule mehr.<br> Die unten abgebildete Tabelle gibt einen exemplarischen Überblick über die vorzunehmenden Einträge einer zweizügigen Grundschule mit jahrgangsbezogenem Halbtagsunterricht.</p><table tabindex="0"><thead><tr><th>Schulinterne Bez.</th><th>Jahrgang</th><th>Parallelität</th><th>Folge-Klasse</th><th>Vorgänger-Klasse</th><th>Klassenart</th></tr></thead><tbody><tr><td>01A</td><td>1E</td><td>A</td><td>02A</td><td></td><td>Regelklasse</td></tr><tr><td>01B</td><td>1E</td><td>B</td><td>02B</td><td></td><td>Regelklasse</td></tr><tr><td>02A</td><td>2E</td><td>A</td><td>03A</td><td>01A</td><td>Regelklasse</td></tr><tr><td>02B</td><td>2E</td><td>B</td><td>03B</td><td>01B</td><td>Regelklasse</td></tr><tr><td>03A</td><td>03</td><td>A</td><td>04A</td><td>02A</td><td>Regelklasse</td></tr><tr><td>03B</td><td>03</td><td>B</td><td>04B</td><td>02B</td><td>Regelklasse</td></tr><tr><td>04A</td><td>04</td><td>A</td><td></td><td>03A</td><td>Regelklasse</td></tr><tr><td>04B</td><td>04</td><td>B</td><td></td><td>03B</td><td>Regelklasse</td></tr></tbody></table><h3 id="grundschule-mit-jahrgangsubergreifendem-unterricht-in-der-schuleingangsphase" tabindex="-1">Grundschule mit jahrgangsübergreifendem Unterricht in der Schuleingangsphase <a class="header-anchor" href="#grundschule-mit-jahrgangsubergreifendem-unterricht-in-der-schuleingangsphase" aria-label="Permalink to &quot;Grundschule mit jahrgangsübergreifendem Unterricht in der Schuleingangsphase&quot;">​</a></h3><p><a href="/bilder/grundschule/tutorials-gs-versetzungstabelle-klassendetails-j-uin-spe.png"><img src="'+u+'" alt="Bei jahrgangsübergreifendem Unterricht in der Schuleingangsphase ist der Jahrgang JU und die Folgeklasse wieder die aktuelle Klasse." loading="lazy"></a></p><p><em>Bei jahrgangsübergreifendem Unterricht in der Schuleingangsphase ist der Jahrgang JU und die <strong>Folgeklasse</strong> wieder die aktuelle Klasse.</em></p><p>Die Klassen-Versetzungstabelle wird bei jahrgangsübergreifendem Unterricht wie im Screenshot ausgefüllt.</p><ul><li>Der Jahrgang wird zu <em>JU</em>.</li><li>Auf die aktuelle Klasse folgt in der Schuleingangsphase als <strong>Folgeklasse</strong> wieder die gleiche Klasse. Ein Übergang beim Schuljahreswechsel findet somit &quot;von dieser Klasse in diese Klasse&quot; statt.</li><li>Als <strong>Klassenart</strong> wird immer <em>Regelklasse</em> eingetragen.</li><li>Nach der jahrgangsübergreifenden Schuleingangsphase gehen die Schüler in die normale Klassenstruktur mit den Jahrgängen 03 und 04 über.</li></ul><p>Der Übergang zur 03 ist manuell oder per Gruppenprozess vorzunehmen, da SchILD-NRW nicht wissen kann, wie die Schüler individuell auf die Folgeklassen im Jahrgang 03 verteilt werden.</p><p>Der Übergang von der 03 zur 04 entspricht in der Regel dem normalen Schema, dass auf die, beispielsweise, &quot;3a&quot; die passende &quot;4a&quot; als Folgeklasse eingetragen wird. Tragen Sie dann hier passend auch im Jahrgang 4 die passenden <strong>Vorgängerklasse</strong>n ein.</p><p>Eine Änderung der Klasse muss bei den Schülern manuell oder per Gruppenprozess eingetragen werden.<br> Die unten abgebildete Tabelle gibt einen exemplarischen Überblick über die vorzunehmenden Einträge einer zweizügigen Grundschule mit jahrgangsübergreifendem Halbtagsunterricht in der Schuleingangsphase.</p><p>In der Tabelle erkennt man, dass an der Schule lediglich die Klassenjahrgänge JU, 03 und 04 verwendet werden, E1, E2 und E3 der Schuleingangsphase werden hier nicht differenziert.</p><table tabindex="0"><thead><tr><th>Schulinterne Bez.</th><th>Jahrgang</th><th>Parallelität</th><th>Folge-Klasse</th><th>Vorgänger-Klasse</th><th>Klassenart</th></tr></thead><tbody><tr><td>Ameisen</td><td>JU</td><td>A</td><td>Ameisen</td><td>Ameisen</td><td>Regelklasse</td></tr><tr><td>Bison</td><td>JU</td><td>B</td><td>Bison</td><td>Bison</td><td>Regelklasse</td></tr><tr><td>Condor</td><td>JU</td><td>C</td><td>Condor</td><td>Condor</td><td>Regelklasse</td></tr><tr><td>Dromedar</td><td>JU</td><td>D</td><td>Dromedar</td><td>Dromedar</td><td>Regelklasse</td></tr><tr><td>03A</td><td>03</td><td>A</td><td>04A</td><td></td><td>Regelklasse</td></tr><tr><td>03B</td><td>03</td><td>B</td><td>04B</td><td></td><td>Regelklasse</td></tr><tr><td>04A</td><td>04</td><td>A</td><td></td><td>03A</td><td>Regelklasse</td></tr><tr><td>04B</td><td>04</td><td>B</td><td></td><td>03B</td><td>Regelklasse</td></tr></tbody></table><h3 id="grundschule-mit-jahrgangsubergreifendem-unterricht-in-allen-jahrgangen" tabindex="-1">Grundschule mit jahrgangsübergreifendem Unterricht in allen Jahrgängen <a class="header-anchor" href="#grundschule-mit-jahrgangsubergreifendem-unterricht-in-allen-jahrgangen" aria-label="Permalink to &quot;Grundschule mit jahrgangsübergreifendem Unterricht in allen Jahrgängen&quot;">​</a></h3><p>In Falle des jahrgangsübergreifenden Unterrichts in allen Jahrgängen ist wie im vorherigen Beispiel zu verfahren, nur dass der Jahrgang <em>JU</em> für alle Jahrgänge und nicht nur die der Schuleingangsphase gesetzt werden.</p><ul><li>Es wird lediglich der <strong>Jahrgang</strong> <em>JU</em> verwendet.</li><li>Als <strong>Klassenart</strong> wird immer <em>Regelklasse</em> eingetragen.</li><li>In allen Klassen wird als <strong>Folgeklasse</strong> und <strong>Vorgängerklasse</strong> die eigene Klasse eingetragen, da die Schüler in der Regel in den Klassen verbleiben.</li></ul><p>Eine Änderung der Klasse muss bei den Schülern manuell oder per Gruppenprozess eingetragen werden.</p><p>Die unten abgebildete Tabelle gibt einen exemplarischen Überblick über die vorzunehmenden Einträge einer zweizügigen Grundschule mit jahrgangsübergreifendem Halbtagsunterricht.</p><table tabindex="0"><thead><tr><th>Schulinterne Bez.</th><th>Jahrgang</th><th>Parallelität</th><th>Folge-Klasse</th><th>Vorgänger-Klasse</th><th>Klassenart</th></tr></thead><tbody><tr><td>Adler</td><td>JU</td><td>A</td><td>Adler</td><td>Adler</td><td>Regelklasse</td></tr><tr><td>Bären</td><td>JU</td><td>B</td><td>Bären</td><td>Bären</td><td>Regelklasse</td></tr><tr><td>Chamäleon</td><td>JU</td><td>C</td><td>Chamäleon</td><td>Chamäleon</td><td>Regelklasse</td></tr><tr><td>Dachs</td><td>JU</td><td>D</td><td>Dachs</td><td>Dachs</td><td>Regelklasse</td></tr><tr><td>Eisbär</td><td>JU</td><td>E</td><td>Eisbär</td><td>Eisbär</td><td>Regelklasse</td></tr><tr><td>Flamingo</td><td>JU</td><td>F</td><td>Flamingo</td><td>Flamingo</td><td>Regelklasse</td></tr><tr><td>Giraffen</td><td>JU</td><td>G</td><td>Giraffen</td><td>Giraffen</td><td>Regelklasse</td></tr><tr><td>Hasen</td><td>JU</td><td>H</td><td>Hasen</td><td>Hasen</td><td>Regelklasse</td></tr></tbody></table><h3 id="forderschulen-jahrgangsubergreifende-klassen" tabindex="-1">Förderschulen: jahrgangsübergreifende Klassen <a class="header-anchor" href="#forderschulen-jahrgangsubergreifende-klassen" aria-label="Permalink to &quot;Förderschulen: jahrgangsübergreifende Klassen&quot;">​</a></h3><p><a href="/bilder/grundschule/tutorials-gs-versetzungstabelle-versetzungstabelle-fs.png"><img src="'+o+'" alt="Eintragung der Klassendaten in Förderschulen in der Klassen-/Versetzungstabelle." loading="lazy"></a></p><p><em>Eintragung der Klassendaten in Förderschulen in der Klassen-/Versetzungstabelle.</em></p><p>Förderschulen haben über die Grundschulen hinaus die Ansicht von weiterführenden Schulen. Dort müssen die Eintragungen der jahrgangsgemischten Klassen folgendermaßen erfolgen:</p><ul><li>Bei der <strong>Statistikbezeichnung</strong> der Klasse ist JUA, JUB, JUC … JUZ einzutragen, wobei <em>JU</em> für <em>&quot;Jahrgangsübergreifend&quot;</em> steht und <em>A</em>-<em>Z</em> die <strong>Parallelität</strong> darstellt. Diese wird für jede weitere Klasse Buchstabe für Buchstabe hochgezählt.</li><li>Der Jahrgang bleibt leer.</li><li>Ohne Jahrgang lässt sich auch keine <strong>Prüfungsordnung</strong> zuordnen, dieser Eintrag bleibt somit ebenfalls leer.</li><li>Die <strong>Vorgängerklasse</strong> und die <strong>Folgeklasse</strong> sind wieder identisch zur aktuellen Klasse.</li><li>Die <strong>Klassenart</strong> ist eine <em>Regelklasse</em>.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Versetzungstabelle_bei_jahrgangsgemischten_Klassen_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4230.</p>',37)])])}const K=s(c,[["render",b]]);export{v as __pageData,K as default};
